let themeEvidence=[],sizePolicyEvidence=[],transportEvidence=[],errorDetailsEvidence=[],retryGeometryEvidence=[];
async function inspectRetryGeometry(){
  for(const status of [502,503,402,401,404,null]){
    const card=status===null?creator.locator('.studio-task-card[data-submission-unknown="true"]'):creator.locator('.studio-task-card.is-failed').filter({hasText:'HTTP '+status});
    const button=card.locator('.studio-task-failed-actions button');await button.waitFor({state:'visible'});
    const measured=await button.evaluate(node=>{
      const card=node.closest('.studio-task-card'),media=node.closest('.studio-task-media'),caption=card.querySelector('.studio-task-caption');
      const box=rect=>({left:rect.left,right:rect.right,top:rect.top,bottom:rect.bottom,width:rect.width,height:rect.height});
      const bounds=node.getBoundingClientRect(),mediaBounds=media.getBoundingClientRect(),captionBounds=caption.getBoundingClientRect(),hit=document.elementFromPoint(bounds.x+bounds.width/2,bounds.y+bounds.height/2),style=getComputedStyle(node);
      return{button:box(bounds),media:box(mediaBounds),caption:box(captionBounds),disabled:node.disabled,visible:style.visibility==='visible'&&style.display!=='none'&&bounds.width>0&&bounds.height>0,
        whollyWithinMedia:bounds.left>=mediaBounds.left-0.5&&bounds.right<=mediaBounds.right+0.5&&bounds.top>=mediaBounds.top-0.5&&bounds.bottom<=mediaBounds.bottom+0.5,
        beforeCaption:bounds.bottom<=captionBounds.top+0.5,centerHitsButton:!!hit&&(hit===node||node.contains(hit)),hit:hit?{tag:hit.tagName,className:String(hit.className)}:null};
    });
    retryGeometryEvidence.push({httpStatus:status,...measured});
    check(status===null?'Unknown retry remains visible within its card while disabled':'HTTP '+status+' original retry fits above the footer and its center is an actual click target',measured.visible&&measured.whollyWithinMedia&&measured.beforeCaption&&(status===null?measured.disabled:!measured.disabled&&measured.centerHitsButton));
  }
}
async function inspectErrorDetails(frame,opener,task,label,{legacy=false,copyFailure=false}={}){
  const expected=task.errorDetails;
  assert.equal(expected?.version,1,label+' exposes the safe details DTO');
  await opener.getByRole('button',{name:'查看错误详情',exact:true}).click();
  const details=frame.getByTestId('gamecowork-task-error-details');await details.waitFor({state:'visible'});
  const fields=await details.locator('[data-error-field]').evaluateAll(nodes=>Object.fromEntries(nodes.map(node=>[node.getAttribute('data-error-field'),node.textContent.trim()])));
  const evidence={label,taskId:task.id,legacy,expected,visibleFields:fields};errorDetailsEvidence.push(evidence);
  for(const key of ['taskId','model','requestedSize','operation','stage','code','httpStatus','elapsedMs','timeoutMs','createdTime','updatedTime']){
    assert.ok(Object.hasOwn(fields,key),label+' shows '+key);
    if(expected[key]!==null&&expected[key]!==undefined)assert.ok(fields[key].includes(String(expected[key])),label+' displays exact '+key+': '+JSON.stringify(fields[key]));
    else assert.match(fields[key],/未记录|未取得|未收到/,label+' explicitly marks unavailable '+key);
  }
  if(legacy){
    check(label+' explicitly shows unrecorded legacy diagnostics without deriving elapsed time from task dates',expected.diagnosticRecorded===false&&['code','operation','stage','elapsedMs','timeoutMs'].every(key=>expected[key]===null&&fields[key].includes('未记录')));
  }else{
    check(label+' displays the actual code, HTTP status, operation/stage, exact elapsed/deadline and original task/model/size',expected.diagnosticRecorded===true&&fields.taskId.includes(task.id)&&fields.model.includes('gpt-image-2')&&fields.requestedSize.includes('3840x2160'));
    if(expected.httpStatus)check(label+' preserves the safe service explanation in its expanded details',expected.serviceMessage===provider.httpErrors[expected.httpStatus]&&(await details.innerText()).includes(provider.httpErrors[expected.httpStatus]));
  }
  if(expected.submissionUnknown)check(label+' explicitly asks the user to check provider records and promises no automatic resubmission',(await details.innerText()).includes('请先核对服务记录')&&(await details.innerText()).includes('不会自动重发'));
  await frame.evaluate(()=>{window.__ownedClipboardFixture.mode='success';});
  const before=await frame.evaluate(()=>window.__ownedClipboardFixture.writes.length);
  await details.getByRole('button',{name:'复制错误详情',exact:true}).click();
  await details.getByRole('status').filter({hasText:'错误详情已复制。'}).waitFor({state:'visible'});
  const writes=await frame.evaluate(()=>window.__ownedClipboardFixture.writes.slice());
  evidence.copiedText=writes[before]?.text;
  check(label+' copies the actual diagnostic text through the product Clipboard API handler',writes.length===before+1&&writes[before].mode==='success'&&evidence.copiedText.includes(task.id)&&evidence.copiedText.includes('gpt-image-2')&&evidence.copiedText.includes('3840x2160')&&!evidence.copiedText.includes(provider.apiKey)&&!evidence.copiedText.includes(provider.baseUrl));
  if(expected.code)assert.ok(evidence.copiedText.includes(expected.code),label+' copied error code');
  if(expected.httpStatus)assert.ok(evidence.copiedText.includes('HTTP 状态：'+expected.httpStatus),label+' copied exact HTTP status');
  if(legacy)assert.match(evidence.copiedText,/未记录/);
  if(copyFailure){
    await frame.evaluate(()=>{
      const state=window.__ownedClipboardFixture;state.mode='denied';
      // Install against the final live Document. The initial Document used by
      // addInitScript can be replaced while this original iframe bootstraps.
      const originalExecCommand=document.execCommand.bind(document);
      Object.defineProperty(document,'execCommand',{configurable:true,value:function ownedClipboardCopyRejected(command,...args){
        if(String(command).toLowerCase()==='copy'){state.fallbackWrites.push({mode:state.mode,text:document.activeElement?.value||window.getSelection()?.toString()||''});return false;}
        return originalExecCommand(command,...args);
      }});
    });
    assert.equal(await frame.evaluate(()=>document.execCommand.name),'ownedClipboardCopyRejected','Final live Document has the owned clipboard fallback guard');
    await details.getByRole('button',{name:'复制错误详情',exact:true}).click();
    try{await details.getByRole('alert').filter({hasText:'复制失败，请手动选择并复制详情内容。'}).waitFor({state:'visible',timeout:8000});}
    catch(error){evidence.clipboardDenialDebug=await frame.evaluate(()=>({state:window.__ownedClipboardFixture,clipboardImplementation:String(navigator.clipboard.writeText),fallbackImplementation:String(document.execCommand)}));throw error;}
    const attempted=await frame.evaluate(()=>window.__ownedClipboardFixture.writes.at(-1));
    const fallback=await frame.evaluate(()=>window.__ownedClipboardFixture.fallbackWrites.at(-1));
    const selectable=await details.evaluate(node=>{const selection=window.getSelection(),range=document.createRange();range.selectNodeContents(node);selection.removeAllRanges();selection.addRange(range);const text=selection.toString();selection.removeAllRanges();return{text,userSelect:getComputedStyle(node).userSelect};});
    evidence.clipboardFailure={attemptedSameText:attempted.text===evidence.copiedText,fallbackAttempted:!!fallback,fallbackSameText:fallback?.text===evidence.copiedText,manualTextContainsTask:selectable.text.includes(task.id),userSelect:selectable.userSelect};
    check(label+' makes both clipboard-path failures visible and keeps actual details available for manual selection',attempted.mode==='denied'&&attempted.text===evidence.copiedText&&fallback?.mode==='denied'&&fallback.text===evidence.copiedText&&selectable.text.includes(task.id)&&selectable.userSelect!=='none');
    await frame.evaluate(()=>{window.__ownedClipboardFixture.mode='success';});
  }
  await snapshot('error-details-'+label,frame);
  await details.getByRole('button',{name:'关闭',exact:true}).click();await details.waitFor({state:'hidden'});
}
