    const record={outcome,taskId:task.id,prompt,compatStatus:task.status,sourceStatus:source.status,submissionUnknown:source.submissionUnknown,diagnostic:source.transportDiagnostic||null,requestSize:call.body.size,postCountAfter:creates().length};
